<div class="chatbot-widget" data-chatbot data-endpoint="/api/chatbot">
    <button class="chatbot-launcher" type="button" aria-expanded="false" aria-controls="chatbot-panel"><span class="chatbot-orbit" aria-hidden="true">✦</span><span class="sr-only">Buka asisten informasi sekolah</span><span class="chatbot-launcher-label">Tanya SMALAN</span></button>
    <section class="chatbot-panel" id="chatbot-panel" hidden aria-label="Asisten informasi sekolah">
        <div class="chatbot-head"><div><span class="chatbot-status-dot"></span><strong>Asisten Informasi SMALAN</strong><small>Berbasis informasi publik website</small></div><button type="button" data-chat-close aria-label="Tutup chat">×</button></div>
        <div class="chatbot-messages" data-chat-messages aria-live="polite" aria-relevant="additions text"><div class="chat-message bot-message">Halo! Saya membantu menemukan informasi resmi SMA Negeri 9 Bandar Lampung dari data yang tersedia di website. Apa yang ingin Anda ketahui?</div></div>
        <div class="chat-suggestions" data-chat-suggestions><button type="button">Di mana alamat sekolah?</button><button type="button">Apa visi sekolah?</button><button type="button">Siapa kepala sekolah?</button></div>
        <form class="chatbot-form" data-chat-form><label class="sr-only" for="chat-question">Pertanyaan</label><input id="chat-question" name="question" maxlength="400" autocomplete="off" placeholder="Tulis pertanyaan Anda…" required><button type="submit" aria-label="Kirim pertanyaan">Kirim</button></form>
        <p class="chatbot-disclaimer">Jawaban diambil dari informasi publik database website, bukan model AI generatif.</p>
    </section>
</div>
